import React, { useState, useEffect } from 'react';
import { Sun, Moon, Palette, Home, Info, Settings, User, LogIn, UserPlus, Globe } from 'lucide-react';

const Header = ({ darkMode, toggleDarkMode }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [colorPaletteOpen, setColorPaletteOpen] = useState(false);
  const [langOpen, setLangOpen] = useState(false);
  const [lang, setLang] = useState("fr");

  const translations = {
    fr: {
      home: "Accueil",
      about: "À propos",
      profile: "Profil",
      settings: "Paramètres",
      login: "Connexion",
      register: "Créer un compte",
      palette: "Palettes de couleurs",
      language: "Langue",
    },
    en: {
      home: "Home",
      about: "About",
      profile: "Profile",
      settings: "Settings",
      login: "Login",
      register: "Register",
      palette: "Color Palettes",
      language: "Language",
    }
  };

  const t = translations[lang];

  // Palettes de couleurs
  const colorPalettes = [
    { name: "Océan", primary: "#0284c7", secondary: "#0ea5e9", accent: "#38bdf8" },
    { name: "Nature", primary: "#16a34a", secondary: "#22c55e", accent: "#4ade80" },
    { name: "Rose", primary: "#db2777", secondary: "#ec4899", accent: "#f472b6" },
    { name: "Violet", primary: "#6d28d9", secondary: "#8b5cf6", accent: "#a78bfa" },
  ];

  // Navigation
  const navItems = [
    { name: t.home, icon: <Home size={18} />, href: '#' },
    { name: t.about, icon: <Info size={18} />, href: '#' },
    { name: t.profile, icon: <User size={18} />, href: '#' },
    { name: t.settings, icon: <Settings size={18} />, href: '#' },
  ];

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-md">
      <div className="container mx-auto px-4 py-3 flex items-center justify-between">

        {/* LOGO */}
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
            <span className="text-white font-bold">R</span>
          </div>
          <h1 className="text-xl font-bold dark:text-white">ReactUI</h1>
        </div>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex items-center space-x-1">
          {navItems.map((item) => (
            <a
              key={item.name}
              href={item.href}
              className="flex items-center space-x-2 px-4 py-2 rounded-lg text-neutral-700 
                         dark:text-neutral-300 hover:bg-neutral-100 
                         dark:hover:bg-neutral-800 transition-all"
            >
              {item.icon}
              <span>{item.name}</span>
            </a>
          ))}
        </nav>

        {/* ACTIONS */}
        <div className="flex items-center space-x-3">

          {/* Language selector */}
          <div className="relative">
            <button
              onClick={() => setLangOpen(!langOpen)}
              className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
            >
              <Globe size={20} />
            </button>

            {langOpen && (
              <div className="absolute right-0 mt-2 w-36 bg-white dark:bg-neutral-800 rounded-lg shadow-lg border dark:border-neutral-700 p-2">
                <button
                  onClick={() => { setLang("fr"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-md"
                >
                  🇫🇷 Français
                </button>
                <button
                  onClick={() => { setLang("en"); setLangOpen(false); }}
                  className="block w-full text-left px-3 py-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-md"
                >
                  🇬🇧 English
                </button>
              </div>
            )}
          </div>

          {/* LOGIN */}
          <a
            href="#"
            className="hidden md:flex items-center space-x-1 px-3 py-2 rounded-lg 
                       bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 
                       dark:hover:bg-neutral-700 transition"
          >
            <LogIn size={18} />
            <span>{t.login}</span>
          </a>

          {/* REGISTER */}
          <a
            href="#"
            className="hidden md:flex items-center space-x-1 px-3 py-2 rounded-lg 
                       bg-primary-600 text-white hover:bg-primary-700 transition"
          >
            <UserPlus size={18} />
            <span>{t.register}</span>
          </a>

          {/* DARK MODE */}
          <button
            onClick={toggleDarkMode}
            className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          {/* MOBILE MENU BUTTON */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            <div className="space-y-1">
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "rotate-45 translate-y-1.5" : ""}`}/>
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "opacity-0" : "opacity-100"}`}/>
              <div className={`w-6 h-0.5 bg-current transition ${mobileMenuOpen ? "-rotate-45 -translate-y-1.5" : ""}`}/>
            </div>
          </button>
        </div>
      </div>

      {/* MOBILE MENU */}
      {mobileMenuOpen && (
        <div className="md:hidden px-4 py-3 space-y-2 border-t dark:border-neutral-800 animate-slide-up">

          {navItems.map((item) => (
            <a
              key={item.name}
              href={item.href}
              className="flex items-center space-x-2 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800"
            >
              {item.icon}
              <span>{item.name}</span>
            </a>
          ))}

          {/* Login mobile */}
          <a className="flex items-center space-x-2 px-4 py-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800" href="#">
            <LogIn size={18}/> <span>{t.login}</span>
          </a>

          {/* Register mobile */}
          <a className="flex items-center space-x-2 px-4 py-3 rounded-lg bg-primary-600 text-white" href="#">
            <UserPlus size={18}/> <span>{t.register}</span>
          </a>
        </div>
      )}
    </header>
  );
};

export default Header;
